public int indexOfExtension(String filename) {
    if (filename == null) {
        return -1;
    }

    int lastSeparator = indexOfLastSeparator(filename);
    int extensionSeparator = filename.lastIndexOf(".");
    int lastPathSeparator = indexOfLastSeparator(filename);

    if (lastSeparator != -1 && extensionSeparator > lastSeparator + 1 && extensionSeparator < lastPathSeparator) {
        return extensionSeparator;
    }

    return -1;
}

/**
 * Returns the index of the last directory separator character. <p> This method will handle a file in either Unix or Windows format. <p> The output will be the same irrespective of the machine that the code is running on.
 * @param path  the path to find the last path separator in, null returns -1
 * @return the index of the last separator character, or -1 if there is no such character
 */
public static int indexOfLastSeparator(String path) {
    if (path == null) {
        return -1;
    }

    int lastUnixPosition = path.lastIndexOf(UNIX_SEPARATOR);
    int lastWindowsPosition = path.lastIndexOf(WINDOWS_SEPARATOR);
    return Math.max(lastUnixPosition, lastWindowsPosition);
}

